package com.starlight.greetings.application;
import com.starlight.greetings.web.ApiException; import java.sql.Timestamp; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class JdbcAdminOperationsService implements AdminOperationsService {private final JdbcTemplate jdbc;public JdbcAdminOperationsService(JdbcTemplate jdbc){this.jdbc=jdbc;}private ApiException bad(String c,String m){return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,c,m);}private void reason(String v){if(v==null||v.trim().length()<2)throw bad("INVALID_REASON","처리 사유를 입력해 주세요.");}private void action(String actor,String action,String target,String reason){jdbc.update("insert into admin_actions(id,actor_user_id,action,target_id,reason) values(?::uuid,?::uuid,?,?,?)",UUID.randomUUID().toString(),actor,action,target,reason);}
 public List<Map<String,Object>> questions(){Instant now=Instant.now();java.time.ZonedDateTime kst=now.atZone(java.time.ZoneId.of("Asia/Seoul"));java.time.LocalDate nextMonday=kst.toLocalDate().with(java.time.DayOfWeek.MONDAY).plusWeeks(1);Instant weekStart=nextMonday.atStartOfDay(java.time.ZoneId.of("Asia/Seoul")).toInstant(),weekEnd=nextMonday.plusWeeks(1).atStartOfDay(java.time.ZoneId.of("Asia/Seoul")).toInstant();var bridges=jdbc.query("select id,name,display_order from bridges where active=true order by display_order",(r,i)->new Object[]{r.getString(1),r.getString(2),r.getInt(3)});var current=jdbc.query("select distinct on(bridge_id) id::text,bridge_id,body,effective_at from questions where status='published' and effective_at<=? order by bridge_id,effective_at desc,id desc",(r,i)->new Object[]{r.getString(1),r.getString(2),r.getString(3),r.getTimestamp(4).toInstant()},Timestamp.from(now));var scheduled=jdbc.query("select id::text,bridge_id,body,effective_at from questions where status='published' and effective_at>? order by effective_at,id",(r,i)->new Object[]{r.getString(1),r.getString(2),r.getString(3),r.getTimestamp(4).toInstant()},Timestamp.from(now));List<Map<String,Object>> result=new ArrayList<>();for(Object[] bridge:bridges){Map<String,Object> item=new LinkedHashMap<>();item.put("bridgeId",bridge[0]);item.put("bridgeName",bridge[1]);item.put("displayOrder",bridge[2]);Object[] active=current.stream().filter(q->q[1].equals(bridge[0])).findFirst().orElse(null);item.put("currentQuestion",active==null?null:Map.of("id",active[0],"body",active[2],"effectiveAt",((Instant)active[3]).toString()));List<Map<String,Object>> future=scheduled.stream().filter(q->q[1].equals(bridge[0])).map(q->Map.<String,Object>of("id",q[0],"body",q[2],"effectiveAt",((Instant)q[3]).toString())).toList();item.put("scheduledQuestions",future);item.put("nextWeekMissing",scheduled.stream().noneMatch(q->q[1].equals(bridge[0])&&!((Instant)q[3]).isBefore(weekStart)&&((Instant)q[3]).isBefore(weekEnd)));result.add(item);}return result;}
 @Transactional public Map<String,Object> createQuestion(Map<String,Object> in,String actor){String bridge=(String)in.get("bridgeId"),body=text(in.get("body"));if(body==null||body.codePointCount(0,body.length())<2||body.codePointCount(0,body.length())>150)throw bad("INVALID_QUESTION","질문은 2~150자로 입력해 주세요.");Instant at=in.get("effectiveAt") instanceof String s?Instant.parse(s):Instant.now();String id=UUID.randomUUID().toString();jdbc.update("insert into questions(id,bridge_id,body,effective_at,status,created_by) values(?::uuid,?,?,?,'published',?::uuid)",id,bridge,body,Timestamp.from(at),actor);action(actor,"question.create",id,null);return Map.of("id",id,"bridgeId",bridge,"body",body,"effectiveAt",at.toString());}
 @Transactional public Map<String,Object> editQuestion(String id,String body,String actor){body=text(body);if(body==null||body.length()<2||body.length()>150)throw bad("INVALID_QUESTION","질문은 2~150자로 입력해 주세요.");var rows=jdbc.query("update questions set body=?,updated_at=now() where id=?::uuid and status='published' returning bridge_id,effective_at",(r,i)->new Object[]{r.getString(1),r.getTimestamp(2)},body,id);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"QUESTION_NOT_FOUND","질문을 찾을 수 없습니다.");action(actor,"question.correct",id,null);return Map.of("id",id,"bridgeId",rows.get(0)[0],"body",body,"effectiveAt",((Timestamp)rows.get(0)[1]).toInstant().toString());}
 public List<Map<String,Object>> seeds(String bridge){return jdbc.query("select id::text,bridge_id,body,display_nickname,theme,status,created_at from letters where is_seed=true and status<>'deleted' and (?::text is null or bridge_id=?) order by created_at desc",(r,i)->Map.of("id",r.getString(1),"bridgeId",r.getString(2),"body",r.getString(3),"displayNickname",r.getString(4),"theme",r.getInt(5),"status",r.getString(6),"createdAt",r.getTimestamp(7).toInstant().toString()),bridge,bridge);}
 @Transactional public Map<String,Object> createSeed(Map<String,Object> in,String actor){String bridge=(String)in.get("bridgeId"),body=text(in.get("body")),name=text(in.get("displayNickname"));int theme=in.get("theme") instanceof Number n?n.intValue():0;if(body==null||name==null||theme<1||theme>4)throw bad("INVALID_SEED","시작 편지 정보를 확인해 주세요.");String id=UUID.randomUUID().toString();jdbc.update("insert into letters(id,bridge_id,display_nickname,body,theme,is_seed,status) values(?::uuid,?,?,?,?,true,'published')",id,bridge,name,body,theme);action(actor,"seed.create",id,null);return Map.of("id",id);}
 @Transactional public Map<String,Object> editSeed(String id,Map<String,Object> in,String actor){String body=text(in.get("body")),name=text(in.get("displayNickname"));int theme=in.get("theme") instanceof Number n?n.intValue():0;if(body==null||name==null||theme<1||theme>4)throw bad("INVALID_SEED","시작 편지 정보를 확인해 주세요.");int count=jdbc.update("update letters set body=?,display_nickname=?,theme=? where id=?::uuid and is_seed=true and status<>'deleted'",body,name,theme,id);if(count==0)throw new ApiException(HttpStatus.NOT_FOUND,"SEED_NOT_FOUND","시작 편지를 찾을 수 없습니다.");action(actor,"seed.edit",id,null);return Map.of("id",id);}
 public List<Map<String,Object>> inquiries(){return jdbc.query("""
 select i.id::text,i.type,i.body,i.related_letter_id::text,i.requester_user_id::text,i.reply_email,i.status,i.created_at,
        l.author_user_id::text as related_letter_author_user_id,u.nickname as related_letter_author_nickname,req_u.nickname as requester_nickname
 from inquiries i
 left join letters l on l.id=i.related_letter_id
 left join users u on l.author_user_id=u.id
 left join users req_u on req_u.id=i.requester_user_id
 where i.status<>'resolved' order by i.created_at
 """,(r,i)->{Map<String,Object> x=new LinkedHashMap<>();x.put("id",r.getString(1));x.put("type",r.getString(2));x.put("body",r.getString(3));x.put("relatedLetterId",r.getString(4));x.put("requesterUserId",r.getString(5));x.put("replyEmail",r.getString(6));x.put("status",r.getString(7));x.put("createdAt",r.getTimestamp(8).toInstant().toString());x.put("relatedLetterAuthorUserId",r.getString("related_letter_author_user_id"));x.put("relatedLetterAuthorNickname",r.getString("related_letter_author_nickname"));x.put("requesterNickname",r.getString("requester_nickname"));return x;});}
 @Transactional public Map<String,Object> updateInquiry(String id,String status,String reason,String actor){if(!Set.of("in_progress","resolved").contains(status))throw bad("INVALID_STATUS","문의 상태를 확인해 주세요.");reason(reason);int n=jdbc.update("update inquiries set status=?,resolved_at=case when ?='resolved' then now() else null end where id=?::uuid and status<>'resolved'",status,status,id);if(n==0)throw new ApiException(HttpStatus.NOT_FOUND,"INQUIRY_NOT_FOUND","문의를 찾을 수 없습니다.");action(actor,"inquiry.update",id,reason.trim());return Map.of("id",id,"status",status);}
 public List<Map<String,Object>> rules(){return jdbc.query("select id::text,category,phrase,active from moderation_rules order by created_at desc",(r,i)->Map.of("id",r.getString(1),"category",r.getString(2),"phrase",r.getString(3),"active",r.getBoolean(4)));}
 @Transactional public Map<String,Object> createRule(Map<String,Object> in,String actor){String cat=text(in.get("category")),phrase=text(in.get("phrase")),why=text(in.get("reason"));if(!Set.of("profanity","advertising","personal_info").contains(cat)||phrase==null||phrase.length()<2||phrase.length()>30)throw bad("INVALID_RULE","검사 규칙을 확인해 주세요.");reason(why);String id=UUID.randomUUID().toString();jdbc.update("insert into moderation_rules(id,category,phrase,created_by) values(?::uuid,?,?,?::uuid)",id,cat,phrase,actor);action(actor,"moderation.create",id,why.trim());return Map.of("id",id);}
 @Transactional public Map<String,Object> setRule(String id,Boolean active,String why,String actor){if(active==null)throw bad("INVALID_STATUS","규칙 상태를 확인해 주세요.");reason(why);int n=jdbc.update("update moderation_rules set active=?,updated_at=now() where id=?::uuid",active,id);if(n==0)throw new ApiException(HttpStatus.NOT_FOUND,"RULE_NOT_FOUND","검사 규칙을 찾을 수 없습니다.");action(actor,"moderation.update",id,why.trim());return Map.of("id",id,"active",active);}
 public List<Map<String,Object>> findLetters(String q,String bridge){q=text(q);if(q==null||q.codePointCount(0,q.length())<2||q.codePointCount(0,q.length())>100)throw bad("INVALID_SEARCH","검색어는 2~100자로 입력해 주세요.");return jdbc.query("""
 select l.id::text,l.bridge_id,l.body,l.display_nickname,l.status,l.theme,l.is_seed,l.created_at,l.author_user_id::text as author_user_id,u.nickname as author_nickname
 from letters l
 left join users u on l.author_user_id=u.id
 where (?::text is null or l.bridge_id=?) and (l.id::text=? or l.author_user_id::text=? or l.body ilike '%'||?||'%' or l.display_nickname ilike '%'||?||'%' or (u.nickname is not null and u.nickname ilike '%'||?||'%'))
 order by l.created_at desc limit 50
 """,(r,i)->{Map<String,Object>x=new LinkedHashMap<>();x.put("id",r.getString(1));x.put("bridgeId",r.getString(2));x.put("body",r.getString(3));x.put("displayNickname",r.getString(4));x.put("status",r.getString(5));x.put("theme",r.getInt(6));x.put("isSeed",r.getBoolean(7));x.put("createdAt",r.getTimestamp(8).toInstant().toString());x.put("authorUserId",r.getString("author_user_id"));x.put("authorNickname",r.getString("author_nickname"));return x;},bridge,bridge,q,q,q,q,q);} public Map<String,Object> alerts(){Integer privacy=jdbc.queryForObject("select count(*)::int from inquiries where type in ('privacy','removal') and status<>'resolved'",Integer.class);var report=jdbc.query("select count(*)::int total,count(*) filter(where status='hidden')::int hidden from letters l where status<>'deleted' and exists(select 1 from reports r where r.letter_id=l.id and r.round=l.report_round and r.status='pending')",(r,i)->new int[]{r.getInt(1),r.getInt(2)}).get(0);return Map.of("privacyInquiries",privacy,"pendingReportLetters",report[0],"hiddenPendingReview",report[1]);}
 public List<Map<String,Object>> auditActions(){return jdbc.query("select a.id::text,a.action,a.target_id,a.reason,a.created_at,u.nickname from admin_actions a join users u on u.id=a.actor_user_id order by a.created_at desc limit 100",(r,i)->Map.<String,Object>of("id",r.getString(1),"action",r.getString(2),"targetId",r.getString(3),"reason",r.getString(4)==null?"":r.getString(4),"createdAt",r.getTimestamp(5).toInstant().toString(),"actorNickname",r.getString(6)));}
 private String text(Object x){return x instanceof String s&&!s.trim().isEmpty()?s.trim():null;}
 // 계정 정지: 정지되면 로그인·작성·신고를 할 수 없고, 현재 로그인 세션도 끊는다. 닉네임은 그대로 묶여 있다.
 private void userId(String id){try{UUID.fromString(id);}catch(Exception e){throw new ApiException(HttpStatus.NOT_FOUND,"USER_NOT_FOUND","회원을 찾을 수 없습니다.");}}
 public List<Map<String,Object>> suspendedUsers(){return jdbc.query("select u.id::text,u.nickname,u.suspended_at,(select a.reason from admin_actions a where a.target_id=u.id::text and a.action='user.suspend' order by a.created_at desc limit 1),(select count(*)::int from letters l where l.author_user_id=u.id) from users u where u.status='suspended' order by u.suspended_at desc nulls last",(r,i)->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getString(1));m.put("nickname",r.getString(2));m.put("suspendedAt",r.getTimestamp(3)==null?null:r.getTimestamp(3).toInstant().toString());m.put("reason",r.getString(4));m.put("letterCount",r.getInt(5));return m;});}
 @Transactional public Map<String,Object> suspendUser(String id,String reason,String actor){reason(reason);userId(id);var rows=jdbc.query("update users set status='suspended',suspended_at=now() where id=?::uuid and status='active' and role='member' returning nickname",(r,i)->r.getString(1),id);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"USER_NOT_FOUND","정지할 수 있는 회원을 찾을 수 없습니다.");jdbc.update("update sessions set revoked_at=now() where user_id=?::uuid and revoked_at is null",id);action(actor,"user.suspend",id,reason.trim());return Map.of("id",id,"nickname",rows.get(0),"status","suspended");}
 @Transactional public Map<String,Object> restoreUser(String id,String reason,String actor){reason(reason);userId(id);var rows=jdbc.query("update users set status='active',suspended_at=null where id=?::uuid and status='suspended' returning nickname",(r,i)->r.getString(1),id);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"USER_NOT_FOUND","정지된 회원을 찾을 수 없습니다.");action(actor,"user.restore",id,reason.trim());return Map.of("id",id,"nickname",rows.get(0),"status","active");}
}
